    static void focusVisibilityChanged(boolean visible){focusScreenVisible=visible;AdibFloatingTimerService service=liveService;if(service==null||service.destroyed)return;if(visible){service.removeOverlayView();return;}android.content.SharedPreferences p=service.getSharedPreferences(PREFS,MODE_PRIVATE);if(!p.getBoolean("active",false)||p.getBoolean("stopped",false))return;service.running=p.getBoolean("running",false);service.endAt=p.getLong("endAt",0);service.remainingMs=p.getLong("remainingMs",0);service.taskId=p.getString("taskId","");service.label=p.getString("label","Pomodoro");service.mode=p.getString("mode","work");service.duration=p.getInt("duration",25);service.globalTimer=p.getBoolean("global",false);service.miniMode=p.getBoolean("mini",false);if(service.running&&service.endAt<=System.currentTimeMillis()){service.handler.removeCallbacks(service.tick);service.tick.run();}else if(Settings.canDrawOverlays(service))service.showOverlay();}
