    private final Runnable tick=new Runnable(){@Override public void run(){if(!running){updateClock(remainingMs);return;}long left=endAt-System.currentTimeMillis();if(left<=0){completeTimer();return;}remainingMs=left;updateClock(left);handler.postDelayed(this,1000);}};

