    private void showMiniOverlay(int oldX,int oldY){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.HORIZONTAL);root.setGravity(Gravity.CENTER);root.setPadding(dp(10),dp(5),dp(10),dp(5));root.setBackground(rounded(HybridUi.surface(true)));root.setElevation(dp(10));root.setContentDescription("Pomodoro vaxtı — toxunaraq genişləndirin");
        clock=new TextView(this);clock.setTextColor(HybridUi.accent(true));clock.setTextSize(15);clock.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);clock.setGravity(Gravity.CENTER);clock.setContentDescription("Pomodoro vaxtı");root.addView(clock,new LinearLayout.LayoutParams(-1,dp(36)));
        title=null;params=new WindowManager.LayoutParams(dp(82),dp(46),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.x=oldX;params.y=oldY;
        final float[] down={0,0};final int[] origin={0,0};final boolean[] moved={false};final int slop=android.view.ViewConfiguration.get(this).getScaledTouchSlop();
        root.setOnTouchListener((v,event)->{switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:down[0]=event.getRawX();down[1]=event.getRawY();origin[0]=params.x;origin[1]=params.y;moved[0]=false;return true;case MotionEvent.ACTION_MOVE:float dx=event.getRawX()-down[0],dy=event.getRawY()-down[1];if(Math.hypot(dx,dy)>slop)moved[0]=true;if(moved[0]){params.x=origin[0]+(int)dx;params.y=Math.max(0,origin[1]+(int)dy);try{windowManager.updateViewLayout(root,params);}catch(Exception ignored){}}return true;case MotionEvent.ACTION_UP:if(!moved[0]){miniMode=false;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("mini",false).apply();showOverlay();}return true;case MotionEvent.ACTION_CANCEL:return true;}return true;});
        overlay=root;try{windowManager.addView(overlay,params);}catch(Exception e){overlay=null;stopSelf();return;}handler.removeCallbacks(tick);tick.run();
    }
    private TextView overlayButton(String symbol,String description){TextView b=new TextView(this);b.setText(symbol);b.setTextColor(Color.WHITE);b.setTextSize(16);b.setGravity(Gravity.CENTER);b.setContentDescription(description);return b;}
    private void updateClock(long millis){if(clock==null)return;long seconds=Math.max(0,(millis+999)/1000);clock.setText(String.format(Locale.getDefault(),"%02d:%02d",seconds/60,seconds%60));}
    private void toggleFromIsland(){
        if(running){remainingMs=Math.max(0,endAt-System.currentTimeMillis());if(remainingMs<=0){completeTimer();return;}running=false;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("running",false).putLong("remainingMs",remainingMs).putLong("endAt",0).apply();if(globalTimer){syncGlobal(this,"pause",remainingMs);AdibWidgetData.cancelPomodoroTick(this);getSharedPreferences(AdibWidgetData.PREFS,MODE_PRIVATE).edit().putBoolean("pomodoro_stopped",false).putLong("pomodoro_end",0).putLong("pomodoro_remaining",remainingMs).apply();AdibWidgetData.updateFromCache(this,"pomodoro");}else if(!taskId.isEmpty())postPomodoro(taskId,"pause",mode,Math.max(1,(int)((remainingMs+59999)/60000)));}
        else{if(remainingMs<=0){stopFromIsland();return;}endAt=System.currentTimeMillis()+remainingMs;running=true;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("running",true).putLong("remainingMs",0).putLong("endAt",endAt).apply();if(globalTimer){syncGlobal(this,"start",remainingMs);getSharedPreferences(AdibWidgetData.PREFS,MODE_PRIVATE).edit().putBoolean("pomodoro_stopped",false).putLong("pomodoro_end",endAt).putLong("pomodoro_remaining",0).apply();AdibWidgetData.updateFromCache(this,"pomodoro");}else if(!taskId.isEmpty())postPomodoro(taskId,"start",mode,duration);}
        if(pauseButton!=null)pauseButton.setText(running?"Ⅱ":"▶");startForeground(4108,buildNotification());handler.removeCallbacks(tick);tick.run();
    }
    private void stopFromIsland(){
        running=false;remainingMs=0;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("active",false).putBoolean("running",false).putBoolean("stopped",true).putLong("remainingMs",0).putLong("endAt",0).apply();
        if(globalTimer){syncGlobal(this,"reset",0);AdibWidgetData.cancelPomodoroTick(this);getSharedPreferences(AdibWidgetData.PREFS,MODE_PRIVATE).edit().putBoolean("pomodoro_stopped",true).putLong("pomodoro_end",0).putLong("pomodoro_remaining",25*60*1000L).apply();AdibWidgetData.updateFromCache(this,"pomodoro");}else if(!taskId.isEmpty())postPomodoro(taskId,"reset",mode,duration);
        handler.removeCallbacks(tick);removeOverlayView();if(syncMonitoring)startForeground(4108,buildNotification());else{stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
    }
    private int statusBarHeight(){int id=getResources().getIdentifier("status_bar_height","dimen","android");return id>0?getResources().getDimensionPixelSize(id):dp(24);}
    private void postCompletionNotification(){postCompletionNotification(this,endAt,taskId,label,mode);}
    static void postCompletionNotification(Context context,long completedEndAt,String completedTaskId,String completedLabel,String completedMode){
        Context app=context.getApplicationContext();
        android.content.SharedPreferences prefs=app.getSharedPreferences(PREFS,MODE_PRIVATE);
        if(completedEndAt>0&&prefs.getLong("notified_end_at",0)==completedEndAt)return;
        if(completedEndAt>0)prefs.edit().putLong("notified_end_at",completedEndAt).apply();
        try{
            NotificationManager nm=(NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE);
            if(nm==null)return;
            if(Build.VERSION.SDK_INT>=26&&!nm.getNotificationChannels().stream().anyMatch(c->FINISH_CHANNEL.equals(c.getId()))){
                NotificationChannel done=new NotificationChannel(FINISH_CHANNEL,"Pomodoronun bitməsi",NotificationManager.IMPORTANCE_HIGH);
                done.setDescription("Taymer bitdikdə səsli bildiriş");
                done.enableVibration(true);done.setVibrationPattern(new long[]{0,250,150,250});
                done.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());
                nm.createNotificationChannel(done);
            }
            Intent open=new Intent(app,OnlineMainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);
            if(completedTaskId!=null&&!completedTaskId.isEmpty()&&!"00000000-0000-4000-8000-000000000001".equals(completedTaskId)){open.setAction(MainActivity.ACTION_WIDGET_TASK);open.putExtra("widget_id",completedTaskId);}
            PendingIntent pi=PendingIntent.getActivity(app,4109,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
            String notificationTitle="break".equals(completedMode)?"Fasilə bitdi":"Pomodoro bitdi";
            Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(app,FINISH_CHANNEL):new Notification.Builder(app);
            Notification n=builder.setSmallIcon(R.drawable.ic_adib).setContentTitle(notificationTitle).setContentText((completedLabel==null?"Pomodoro":completedLabel)+" · vaxt bitdi").setContentIntent(pi).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_HIGH).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PUBLIC).setTimeoutAfter(20000).build();
            nm.notify(4110,n);
        }catch(SecurityException ignored){}
    }
    static void notifyTimerFinished(Context context,long completedEndAt,String taskId,String label,String mode){postCompletionNotification(context,completedEndAt,taskId,label,mode);}
    private void completeTimer(){handler.removeCallbacks(tick);getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("active",false).putBoolean("running",false).putBoolean("stopped",true).putLong("remainingMs",0).apply();if(!globalTimer&&!taskId.isEmpty())postPomodoro(taskId,mode.equals("break")?"break-finish":"finish",mode,duration);if(globalTimer){syncGlobal(this,"finish",0);AdibWidgetData.cancelPomodoroTick(this);android.content.SharedPreferences p=getSharedPreferences(AdibWidgetData.PREFS,MODE_PRIVATE);p.edit().putBoolean("pomodoro_stopped",true).putLong("pomodoro_end",0).putLong("pomodoro_remaining",0).apply();AdibWidgetData.updateFromCache(this,"pomodoro");}postCompletionNotification();hideOverlay();if(syncMonitoring)startForeground(4108,buildNotification());else{stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}}
    void dismissOverlay(){android.content.SharedPreferences p=getSharedPreferences(PREFS,MODE_PRIVATE);SharedPomodoroState.dismiss(p,taskId+"|"+p.getString("session_id",""),p.getString("shared_visibility_id",""));removeOverlayView();if(!taskId.isEmpty()&&!Boolean.getBoolean("adib.testing"))postPomodoro(taskId,"hide",mode,duration);}
    private void removeOverlayView(){if(overlay!=null){try{windowManager.removeView(overlay);}catch(Exception ignored){}overlay=null;clock=null;title=null;}}
    private void hideOverlay(){handler.removeCallbacks(tick);removeOverlayView();}
    private static void setWebSession(HttpURLConnection c){try{String base=BuildConfig.APP_BASE_URL;c.setRequestProperty("Origin",base.replaceAll("/$",""));c.setRequestProperty("Referer",base);String cookie=CookieManager.getInstance().getCookie(base);if(cookie!=null&&!cookie.isEmpty())c.setRequestProperty("Cookie",cookie);}catch(Exception ignored){}}
    private static JSONObject readJson(java.io.InputStream in)throws Exception{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>1024*1024)throw new java.io.IOException("Pomodoro response too large");}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}
    private void postPomodoro(String id,String action,String currentMode,int minutes){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putLong("local_mutation_until",System.currentTimeMillis()+15000).apply();final String sentSessionId=getSharedPreferences(PREFS,MODE_PRIVATE).getString("session_id",""),sentVisibilityId=getSharedPreferences(PREFS,MODE_PRIVATE).getString("shared_visibility_id","");IO.execute(()->{HttpURLConnection c=null;try{DirectRuntime.init(AdibFloatingTimerService.this);if(DirectRuntime.enabled()){android.content.SharedPreferences p=getSharedPreferences(PREFS,MODE_PRIVATE);JSONObject body=new JSONObject().put("id",id).put("action",action).put("mode",currentMode).put("duration",Math.max(1,minutes)).put("remainingSeconds",Math.max(0,(remainingMs+999)/1000)).put("sessionId",sentSessionId);if("hide".equals(action))body.put("expectedVisibilityId",sentVisibilityId);JSONObject result=DirectRuntime.request("POST","/api/personal-pomodoro",body);handler.post(()->{p.edit().putLong("local_mutation_until",0).apply();if(!destroyed&&result.optJSONObject("timer")!=null)try{applySharedSnapshot(new JSONObject().put("serverNow",result.optLong("serverNow")).put("timers",new org.json.JSONArray().put(result.getJSONObject("timer"))));}catch(Exception ignored){}});return;}String base=BuildConfig.APP_BASE_URL;String uri=base.endsWith("/")?base.substring(0,base.length()-1)+"/api/personal-pomodoro":base+"/api/personal-pomodoro";c=(HttpURLConnection)new URL(uri).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(7000);c.setReadTimeout(12000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");setWebSession(c);JSONObject body=new JSONObject();body.put("id",id);body.put("action",action);body.put("mode",currentMode);body.put("duration",Math.max(1,minutes));android.content.SharedPreferences p=getSharedPreferences(PREFS,MODE_PRIVATE);p.edit().putLong("local_mutation_until",System.currentTimeMillis()+15000).apply();body.put("remainingSeconds",Math.max(0,(remainingMs+999)/1000));body.put("sessionId",sentSessionId);if("hide".equals(action))body.put("expectedVisibilityId",sentVisibilityId);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()==200)try(java.io.InputStream in=c.getInputStream()){JSONObject result=readJson(in);handler.post(()->{getSharedPreferences(PREFS,MODE_PRIVATE).edit().putLong("local_mutation_until",0).apply();if(!destroyed&&result.optJSONObject("timer")!=null)try{JSONObject data=new JSONObject().put("serverNow",result.optLong("serverNow")).put("timers",new org.json.JSONArray().put(result.getJSONObject("timer")));applySharedSnapshot(data);}catch(Exception ignored){}});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}});}
    @Override public void onDestroy(){destroyed=true;if(liveService==this)liveService=null;handler.removeCallbacks(remotePoll);handler.removeCallbacks(commentPoll);hideOverlay();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
